fn all_characters_same(s: &[u8]) -> bool {
    // Edge case: empty array or single-element array
    if s.len() <= 1 {
        return true;
    }

    // Get the first byte to compare against
    let first_char = s[0];

    // Check if all characters are the same as the first one
    for &byte in s.iter() {
        if byte != first_char {
            return false; // Found a different byte
        }
    }

    true // All bytes are the same
}